const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const orgs = status === 200 && Array.isArray(raw.body) ? raw.body : [];
const from = new Date(Date.now() - 90 * 86400000).toISOString().slice(0, 10);
const to = new Date().toISOString().slice(0, 10);
return [{ json: {
  connectionsStatus: status,
  tenantId: orgs[0]?.tenantId ?? '',
  organisationName: orgs[0]?.tenantName ?? '',
  organisationCount: orgs.length,
  fromDate: from, toDate: to,
} }];

const tenant = $('Read Tenant').first().json;
const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const accounts = status === 200 ? (raw.body?.Accounts ?? []) : [];
const banks = accounts.filter((a) => String(a.Type ?? '') === 'BANK' && String(a.Status ?? '') === 'ACTIVE');
return [{ json: { ...tenant,
  accountsStatus: status,
  accountsTotal: accounts.length,
  bankAccountCount: banks.length,
  bankAccountId: banks[0]?.AccountID ?? '',
  bankAccountName: banks[0]?.Name ?? '',
  sampleAccount: accounts[0] ? { Code: accounts[0].Code, Name: accounts[0].Name, Type: accounts[0].Type } : null,
} }];

const ctx = $('Pick First Bank Account').first().json;
const grab = (name) => { try { return $(name).first().json ?? {}; } catch { return { _unexecuted: true }; } };
const statusOf = (raw) => Number(raw.statusCode ?? 0) || (raw._unexecuted ? 'not run' : 'no response');

const statement = grab('Try Bank Statement Report');
const unreconciled = grab('Try Unreconciled BankTransactions');
const invoices = grab('Try Unpaid Invoices');
const taxRates = grab('Try Tax Rates');
const contacts = grab('Try Contacts');
const finance = grab('Try Finance BankStatementsPlus');

// The whole point of the spike: does the ordinary Accounting API hand back
// bank statement lines with a reconciled flag, or does it not?
const report0 = (statement.body?.Reports ?? [])[0] ?? {};
const headerRow = (report0.Rows ?? []).find((r) => String(r.RowType ?? '') === 'Header');
const columns = (headerRow?.Cells ?? []).map((c) => String(c?.Value ?? ''));
const dataRows = (report0.Rows ?? []).flatMap((s) => s.Rows ?? []);
const hasReconciled = columns.some((c) => /reconciled/i.test(c));
const sampleRow = dataRows[0] ? (dataRows[0].Cells ?? []).map((c) => String(c?.Value ?? '')) : [];

const statementOk = Number(statement.statusCode ?? 0) === 200 && columns.length > 0;
const outcome = statementOk && hasReconciled ? 'A2' : 'B';

const lines = [];
lines.push('=== XERO SPIKE RESULT ===');
lines.push('');
lines.push(`OUTCOME: ${outcome}`);
lines.push(outcome === 'A2'
  ? 'The Bank Statement report returns statement lines with a Reconciled column, so the skill can work from the real queue and the write lane is worth having.'
  : 'The Bank Statement report did not return usable statement lines. Build outcome B: coding review over unreconciled BankTransactions and unpaid invoices, and drop the write lane (108, the write credential, policy rule 6 and its policy entry).');
lines.push('');
lines.push(`Organisation: ${ctx.organisationName || '(none)'}  (${ctx.organisationCount} authorised)`);
lines.push(`Bank accounts: ${ctx.bankAccountCount}  first: ${ctx.bankAccountName || '(none)'}`);
lines.push('');
lines.push('Endpoint results:');
lines.push(`- GET /connections                      ${ctx.connectionsStatus}`);
lines.push(`- GET /Accounts                         ${ctx.accountsStatus}  (${ctx.accountsTotal} accounts)`);
lines.push(`- GET /Reports/BankStatement            ${statusOf(statement)}  (${dataRows.length} rows, ${columns.length} columns)`);
lines.push(`- GET /BankTransactions IsReconciled==false  ${statusOf(unreconciled)}  (${(unreconciled.body?.BankTransactions ?? []).length} rows)`);
lines.push(`- GET /Invoices AUTHORISED              ${statusOf(invoices)}  (${(invoices.body?.Invoices ?? []).length} rows)`);
lines.push(`- GET /TaxRates                         ${statusOf(taxRates)}  (${(taxRates.body?.TaxRates ?? []).length} rates)`);
lines.push(`- GET /Contacts                         ${statusOf(contacts)}  (${(contacts.body?.Contacts ?? []).length} rows)`);
lines.push(`- GET finance.xro BankStatementsPlus    ${statusOf(finance)}  (403 is expected and fine: it needs Xero financial-services partner approval)`);
lines.push('');
lines.push('Bank Statement report columns, in order:');
lines.push(columns.length ? `  ${JSON.stringify(columns)}` : '  (none returned)');
lines.push(`  Reconciled column present: ${hasReconciled ? 'yes' : 'NO'}`);
lines.push('First data row, as cell values:');
lines.push(sampleRow.length ? `  ${JSON.stringify(sampleRow)}` : '  (no rows in this date range)');
lines.push('');
lines.push('Tax types available (the skill may only ever use these):');
lines.push(`  ${JSON.stringify((taxRates.body?.TaxRates ?? []).map((r) => r.TaxType).slice(0, 12))}`);
lines.push('');
lines.push('Rate limit headroom at the end of this run:');
lines.push(`  day ${contacts.headers?.['x-daylimit-remaining'] ?? '?'}  minute ${contacts.headers?.['x-minlimit-remaining'] ?? '?'}`);
lines.push('');
lines.push('If the columns above are not Date, Description, Reference, Reconciled,');
lines.push('Source, Amount, Balance, that is fine: the parser reads them by name.');
lines.push('Paste this whole block back to whoever is building the skill.');

return [{ json: { outcome, columns, hasReconciled, sampleRow, statementRowCount: dataRows.length,
  summary: lines.join('\n') } }];
